local module = {}
module.__index = module
module.className = "Command"
local _commands = {}

function module.new(vm, cmdName)
    local self = {}
    self.Name = cmdName
    self._executeFunc = function(...)
        return vm[cmdName](vm, ...)
    end
    if vm["Can" .. cmdName] then
        self._canExecuteFunc = function(...)
            return vm["Can" .. cmdName](vm, ...)
        end
    end
    self._event = Instance.new("BindableEvent")
    setmetatable(self, module)
    return self
end

function module.Get(vm, cmdName)
    if not _commands[vm] then
        _commands[vm] = {}
    end
    if not _commands[vm][cmdName] then
        _commands[vm][cmdName] = module.new(vm, cmdName)
    end
    return _commands[vm][cmdName]
end

function module:Execute(...)
    local suc, res = pcall(function(...)
        local args = table.pack(self._executeFunc(...))
        self._event:Fire("After", ...)
        return args
    end, ...)
    
    if not suc then
        warn(res)
        warn(debug.traceback())
    else
        return table.unpack(res)
    end
end

function module:CanExecute(...)
    local res, err = self._canExecuteFunc == nil
    if not res then
        res, err = self._canExecuteFunc(...)
    end
    return res, err
end

return module